<?php
require_once __DIR__.'/../includes/auth.php';require_login();$db=db();$uid=(int)user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['generate'])){for($attempt=0;$attempt<5;$attempt++){$code=strtoupper(substr(bin2hex(random_bytes(6)),0,8));$s=$db->prepare('INSERT INTO student_parent_codes(student_id,link_code,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 24 HOUR)) ON DUPLICATE KEY UPDATE link_code=VALUES(link_code),expires_at=VALUES(expires_at),created_at=NOW()');$s->bind_param('is',$uid,$code);if($s->execute()){flash('success','A new Grade '.user_grade_number().' parent link code was created.');redirect('student/parent_access.php');}if($s->errno!==1062)break;}flash('error','A parent code could not be created. Please try again.');redirect('student/parent_access.php');}if(isset($_POST['remove'])){$parentId=(int)$_POST['remove'];$s=$db->prepare('DELETE FROM parent_student_links WHERE student_id=? AND parent_id=?');$s->bind_param('ii',$uid,$parentId);$s->execute();flash('success','Parent access removed.');redirect('student/parent_access.php');}}
$code=query_one('SELECT link_code,expires_at FROM student_parent_codes WHERE student_id=? AND expires_at>NOW()','i',[$uid]);$s=$db->prepare('SELECT p.id,p.full_name,p.email,psl.linked_at FROM parent_student_links psl JOIN parents p ON p.id=psl.parent_id WHERE psl.student_id=?');$s->bind_param('i',$uid);$s->execute();$linked=$s->get_result();$pageTitle='Parent access';include __DIR__.'/../includes/header.php';?>
<h1>Parent monitoring access</h1><section class="card"><span class="badge">Grade <?=user_grade_number()?> student</span><h2>Link a parent safely</h2><p>Create a code and give it only to your parent or guardian. They must enter it in the Parent Dashboard within 24 hours.</p><?php if($code):?><div style="font-size:clamp(1.7rem,9vw,2.5rem);font-weight:900;letter-spacing:.18em;margin:15px 0"><?=e($code['link_code'])?></div><p class="muted">Valid until <?=e(date('d M Y, g:i A',strtotime($code['expires_at'])))?></p><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="generate" value="1"><button type="submit"><?=$code?'Replace with a new code':'Generate parent link code'?></button></form></section>
<section class="card"><h2>Parents with access</h2><?php if(!$linked->num_rows):?><p class="muted">No parent is linked yet.</p><?php endif;while($p=$linked->fetch_assoc()):?><div class="row" style="justify-content:space-between"><p><strong><?=e($p['full_name'])?></strong><br><span class="muted"><?=e($p['email'])?></span></p><form method="post"><?=csrf_field()?><input type="hidden" name="remove" value="<?=intval($p['id'])?>"><button type="submit" class="danger">Remove</button></form></div><?php endwhile;?></section>
<?php include __DIR__.'/../includes/footer.php';
